package org.researchdock.mobile;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class OriginalFilesTest {
 private JSONObject item(String name,String type,String state,String hash)throws Exception{return new JSONObject().put("name",name).put("type",type).put("status",state).put("asset_id",hash);}
 @Test public void sourceInventoryAndSupplementalAssetsDoNotDuplicateReadyFiles()throws Exception{JSONObject source=item("报告.pdf","pdf","ready","hash1").put("id","source1");JSONObject doc=new JSONObject().put("attachments",new JSONArray().put(source).put(item("音频.mp3","audio","missing","").put("id","source2"))).put("assets",new JSONArray().put(new JSONObject().put("id","hash1").put("type","pdf").put("name","报告.pdf")).put(new JSONObject().put("id","hash2").put("type","image").put("name","笔记原图")));java.util.List<OriginalFiles.Entry> result=OriginalFiles.entries(doc);assertEquals(3,result.size());assertTrue(result.get(0).source);assertFalse(result.get(2).source);assertEquals("hash2",result.get(2).item.getString("asset_id"));}
 @Test public void formatStateLocalAndFilenameFiltersAreIndependent()throws Exception{JSONObject doc=new JSONObject().put("title","汇总研究");JSONObject pdf=item("半导体报告.pdf","pdf","ready","hash");assertTrue(OriginalFiles.matches(doc,pdf,"半导体","pdf","ready",false));assertFalse(OriginalFiles.matches(doc,pdf,"","audio","",false));assertFalse(OriginalFiles.matches(doc,pdf,"","","local",false));assertTrue(OriginalFiles.matches(doc,pdf,"","","local",true));assertFalse(OriginalFiles.matches(doc,pdf,"xlsx","","",true));JSONObject audio=item("交流.mp3","audio","missing","");assertTrue(OriginalFiles.matches(doc,audio,"","audio","missing",false));assertFalse(OriginalFiles.matches(doc,audio,"","audio","ready",false));}
 @Test public void sameRevisionReusesImmutableBodyAndLatestMetadata()throws Exception{JSONObject cached=new JSONObject().put("document_id","doc-test").put("revision",3).put("sequence",10).put("body","完整正文，不截断").put("summary","旧摘要");JSONObject catalog=new JSONObject().put("document_id","doc-test").put("revision",3).put("sequence",20).put("summary","更新后的摘要").put("attachments",new JSONArray().put(item("新附件.pdf","pdf","ready","hash")));JSONObject merged=OriginalFiles.mergeCached(cached,catalog);assertNotNull(merged);assertEquals("完整正文，不截断",merged.getString("body"));assertEquals("更新后的摘要",merged.getString("summary"));assertEquals(20,merged.getInt("sequence"));assertEquals(1,merged.getJSONArray("attachments").length());assertEquals("旧摘要",cached.getString("summary"));}
 @Test public void differentRevisionOrIdentityNeverBorrowsOldText()throws Exception{JSONObject cached=new JSONObject().put("document_id","one").put("revision",1).put("body","旧正文");assertNull(OriginalFiles.mergeCached(cached,new JSONObject().put("document_id","one").put("revision",2)));assertNull(OriginalFiles.mergeCached(cached,new JSONObject().put("document_id","two").put("revision",1)));assertNull(OriginalFiles.mergeCached(new JSONObject().put("document_id","one").put("revision",1),new JSONObject().put("document_id","one").put("revision",1)));}
}
